import dpstf2 = require( './index' );


// TESTS //

const A = new Float64Array( 4 );
const PIV = new Int32Array( 2 );
const RANK = new Int32Array( 1 );
const WORK = new Float64Array( 4 );

// Numeric status and rank/permutation outputs have separate roles:
dpstf2( 'row-major', 'upper', 2, A, 2, PIV, RANK, -1, WORK ); // $ExpectType number
dpstf2( 'column-major', 'lower', 2, A, 2, PIV, RANK, -1, WORK ); // $ExpectType number
dpstf2( 101, 121, 2, A, 2, PIV, RANK, -1, WORK ); // $ExpectType number
dpstf2( 102, 122, 2, A, 2, PIV, RANK, -1, WORK ); // $ExpectType number
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, 1, 0, RANK, 0, -1, WORK, 1, 0 ); // $ExpectType number
dpstf2.ndarray( 122, 2, A, -2, -1, 3, PIV, -1, 1, RANK, 0, -1, WORK, -1, 3 ); // $ExpectType number

// Invalid enums, primitive tolerance and buffer roles are rejected:
dpstf2( 103, 'upper', 2, A, 2, PIV, RANK, -1, WORK ); // $ExpectError
dpstf2( 'row-major', 123, 2, A, 2, PIV, RANK, -1, WORK ); // $ExpectError
// Deliberately supply a boxed primitive to verify its declared rejection:
// eslint-disable-next-line no-new-wrappers
dpstf2( 'row-major', 'upper', 2, A, 2, PIV, RANK, new Number( -1 ), WORK ); // $ExpectError
dpstf2( 'row-major', 'upper', 2, A, 2, WORK, RANK, -1, WORK ); // $ExpectError
dpstf2( 'row-major', 'upper', 2, A, 2, PIV, WORK, -1, WORK ); // $ExpectError
dpstf2.ndarray( 'all', 2, A, 2, 1, 0, PIV, 1, 0, RANK, 0, -1, WORK, 1, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, 1, 0, WORK, 0, -1, WORK, 1, 0 ); // $ExpectError

// Each required dpstf2 argument has its declared type:
dpstf2( false, 'upper', 2, A, 2, PIV, RANK, -1, WORK ); // $ExpectError
dpstf2( 'row-major', false, 2, A, 2, PIV, RANK, -1, WORK ); // $ExpectError
dpstf2( 'row-major', 'upper', false, A, 2, PIV, RANK, -1, WORK ); // $ExpectError
dpstf2( 'row-major', 'upper', 2, false, 2, PIV, RANK, -1, WORK ); // $ExpectError
dpstf2( 'row-major', 'upper', 2, A, false, PIV, RANK, -1, WORK ); // $ExpectError
dpstf2( 'row-major', 'upper', 2, A, 2, false, RANK, -1, WORK ); // $ExpectError
dpstf2( 'row-major', 'upper', 2, A, 2, PIV, false, -1, WORK ); // $ExpectError
dpstf2( 'row-major', 'upper', 2, A, 2, PIV, RANK, false, WORK ); // $ExpectError
dpstf2( 'row-major', 'upper', 2, A, 2, PIV, RANK, -1, false ); // $ExpectError

// Missing and extra arguments are rejected:
dpstf2(); // $ExpectError
dpstf2( 'row-major' ); // $ExpectError
dpstf2( 'row-major', 'upper' ); // $ExpectError
dpstf2( 'row-major', 'upper', 2 ); // $ExpectError
dpstf2( 'row-major', 'upper', 2, A ); // $ExpectError
dpstf2( 'row-major', 'upper', 2, A, 2 ); // $ExpectError
dpstf2( 'row-major', 'upper', 2, A, 2, PIV ); // $ExpectError
dpstf2( 'row-major', 'upper', 2, A, 2, PIV, RANK ); // $ExpectError
dpstf2( 'row-major', 'upper', 2, A, 2, PIV, RANK, -1 ); // $ExpectError
dpstf2( 'row-major', 'upper', 2, A, 2, PIV, RANK, -1, WORK, 0 ); // $ExpectError

// Each required dpstf2.ndarray argument has its declared type:
dpstf2.ndarray( false, 2, A, 2, 1, 0, PIV, 1, 0, RANK, 0, -1, WORK, 1, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', false, A, 2, 1, 0, PIV, 1, 0, RANK, 0, -1, WORK, 1, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, false, 2, 1, 0, PIV, 1, 0, RANK, 0, -1, WORK, 1, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, false, 1, 0, PIV, 1, 0, RANK, 0, -1, WORK, 1, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, false, 0, PIV, 1, 0, RANK, 0, -1, WORK, 1, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, false, PIV, 1, 0, RANK, 0, -1, WORK, 1, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, false, 1, 0, RANK, 0, -1, WORK, 1, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, false, 0, RANK, 0, -1, WORK, 1, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, 1, false, RANK, 0, -1, WORK, 1, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, 1, 0, false, 0, -1, WORK, 1, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, 1, 0, RANK, false, -1, WORK, 1, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, 1, 0, RANK, 0, false, WORK, 1, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, 1, 0, RANK, 0, -1, false, 1, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, 1, 0, RANK, 0, -1, WORK, false, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, 1, 0, RANK, 0, -1, WORK, 1, false ); // $ExpectError

// Missing and extra arguments are rejected:
dpstf2.ndarray(); // $ExpectError
dpstf2.ndarray( 'upper' ); // $ExpectError
dpstf2.ndarray( 'upper', 2 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, 1 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, 1, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, 1, 0, RANK ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, 1, 0, RANK, 0 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, 1, 0, RANK, 0, -1 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, 1, 0, RANK, 0, -1, WORK ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, 1, 0, RANK, 0, -1, WORK, 1 ); // $ExpectError
dpstf2.ndarray( 'upper', 2, A, 2, 1, 0, PIV, 1, 0, RANK, 0, -1, WORK, 1, 0, 0 ); // $ExpectError
